-- 2. Service « Télécommunications » (créé, ou contenu mis à jour s'il existe déjà)
INSERT INTO services (slug, title, icon, short_desc, content, image, form_type, sort, active)
VALUES ('telecommunications', 'Télécommunications', 'antenna', 'Réseaux, téléphonie IP, fibre optique, sécurité électronique : des solutions de communication performantes pour votre entreprise.', '<div class=\"svc-intro\">\n<p class=\"lead\"><strong>AFAM Print &amp; Services</strong> accompagne les entreprises dans leur transformation numérique grâce à des solutions de télécommunication, de connectivité et d\'infrastructures réseau adaptées à leurs besoins.</p>\n<p>Nous mettons notre expertise au service des professionnels pour faciliter les échanges, améliorer la connectivité et renforcer la performance de leurs infrastructures informatiques et de communication.</p>\n</div>\n\n<h2>Nos solutions</h2>\n<div class=\"svc-grid\">\n<div class=\"svc-card\">\n<img src=\"{site_url}/assets/img/contenus/telecom-reseau.jpg\" alt=\"Baie de brassage réseau\" loading=\"lazy\">\n<div class=\"svc-body\">\n<h3>Réseaux et connectivité</h3>\n<p>Installation et configuration de réseaux informatiques, câblage structuré et équipements réseau.</p>\n<ul>\n<li>Installation et configuration de réseaux informatiques</li>\n<li>Câblage réseau et brassage</li>\n<li>Fourniture et installation de switchs, routeurs et points d\'accès Wi-Fi</li>\n<li>Extension et optimisation de la couverture réseau</li>\n</ul>\n</div>\n</div>\n<div class=\"svc-card\">\n<img src=\"{site_url}/assets/img/contenus/telecom-telephonie.jpg\" alt=\"Téléphone IP professionnel\" loading=\"lazy\">\n<div class=\"svc-body\">\n<h3>Téléphonie professionnelle</h3>\n<p>Solutions de téléphonie IP et systèmes de communication adaptés aux entreprises.</p>\n<ul>\n<li>Fourniture et installation de téléphones IP</li>\n<li>Mise en place de solutions de téléphonie sur IP (VoIP)</li>\n<li>Installation et configuration de standards téléphoniques IPBX</li>\n<li>Solutions de communication interne et externe</li>\n</ul>\n</div>\n</div>\n<div class=\"svc-card\">\n<div class=\"svc-visual\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M2 12h5l3-8 4 16 3-8h5\"/></svg></div>\n<div class=\"svc-body\">\n<h3>Fibre optique et infrastructures</h3>\n<p>Solutions de connectivité pour améliorer la rapidité et la fiabilité des échanges de données.</p>\n<ul>\n<li>Raccordement et déploiement de liaisons fibre optique</li>\n<li>Infrastructures et baies de brassage</li>\n<li>Interconnexion de sites et de bâtiments</li>\n</ul>\n</div>\n</div>\n<div class=\"svc-card\">\n<div class=\"svc-visual\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 7l13 4-1.5 4.5L2 11.5z\"/><path d=\"M16 11l4-1.5M8 13.6V18H4\"/><circle cx=\"6\" cy=\"9.4\" r=\".6\"/></svg></div>\n<div class=\"svc-body\">\n<h3>Sécurité électronique</h3>\n<p>Solutions de vidéosurveillance et de contrôle d\'accès, selon les besoins de votre organisation.</p>\n<ul>\n<li>Vidéosurveillance (caméras IP, enregistreurs, consultation à distance)</li>\n<li>Contrôle d\'accès (badges, digicodes, pointeuses)</li>\n<li>Étude et dimensionnement selon vos locaux</li>\n</ul>\n</div>\n</div>\n<div class=\"svc-card\">\n<img src=\"{site_url}/assets/img/contenus/telecom-visio.jpg\" alt=\"Salle de visioconférence\" loading=\"lazy\">\n<div class=\"svc-body\">\n<h3>Visioconférence et communication</h3>\n<p>Équipements et solutions de collaboration pour vos réunions à distance.</p>\n<ul>\n<li>Équipements de visioconférence</li>\n<li>Caméras, microphones et systèmes audio</li>\n<li>Écrans professionnels et solutions de collaboration à distance</li>\n</ul>\n</div>\n</div>\n<div class=\"svc-card\">\n<img src=\"{site_url}/assets/img/contenus/telecom-technicien.jpg\" alt=\"Technicien intervenant sur une baie réseau\" loading=\"lazy\">\n<div class=\"svc-body\">\n<h3>Installation et maintenance</h3>\n<p>Accompagnement technique, entretien des équipements et assistance pour assurer la continuité de vos activités.</p>\n<ul>\n<li>Installation et mise en service des équipements</li>\n<li>Maintenance préventive et corrective</li>\n<li>Diagnostic et résolution des incidents</li>\n<li>Accompagnement technique et suivi des installations</li>\n</ul>\n</div>\n</div>\n</div>\n\n<h2>Pourquoi choisir AFAM Print &amp; Services ?</h2>\n<p>Nous privilégions des solutions fiables, évolutives et adaptées aux exigences de chaque organisation. Notre approche repose sur l\'écoute de vos besoins, le conseil, la qualité des équipements et l\'accompagnement technique.</p>\n<div class=\"about-grid\">\n<div class=\"about-card\"><h3>Des équipements fiables et performants</h3><p>Issus des plus grandes marques du marché.</p></div>\n<div class=\"about-card\"><h3>Une équipe technique qualifiée</h3><p>Pour une installation et une maintenance de qualité.</p></div>\n<div class=\"about-card\"><h3>Des solutions sur mesure</h3><p>Adaptées à la taille et aux besoins de votre entreprise.</p></div>\n<div class=\"about-card\"><h3>Un accompagnement de proximité</h3><p>Du conseil à la mise en service.</p></div>\n<div class=\"about-card\"><h3>Une réactivité garantie</h3><p>Pour assurer la continuité de votre activité.</p></div>\n</div>\n<p>Notre objectif est de vous aider à disposer d\'une infrastructure de communication performante, sécurisée et adaptée au développement de votre activité.</p>\n\n<div class=\"about-cta\">\n<h2>Construisons ensemble votre solution</h2>\n<p>Vous souhaitez moderniser votre réseau, améliorer vos communications ou équiper vos locaux professionnels ? Contactez AFAM Print &amp; Services pour étudier vos besoins et bénéficier d\'une proposition adaptée à votre entreprise.</p>\n<p><a class=\"btn btn-accent\" href=\"#formulaire\">Étudier mon projet</a> <a class=\"btn btn-outline\" href=\"tel:{phone_link}\">Appeler le {phone}</a> <a class=\"btn btn-outline\" href=\"mailto:{email}\">{email}</a></p>\n</div>\n', 'assets/img/contenus/telecom-hero.jpg', 'quote', (SELECT COALESCE(MAX(s.sort), 0) + 1 FROM (SELECT sort FROM services) s), 1)
ON DUPLICATE KEY UPDATE content = VALUES(content), short_desc = VALUES(short_desc), icon = VALUES(icon), image = COALESCE(NULLIF(image, ''), VALUES(image)), form_type = VALUES(form_type), active = 1;

